<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller;use App\Services\Trading\TradingCalculator;use Illuminate\Http\Request;
final class CalculatorController extends Controller {public function __construct(private TradingCalculator $c){}public function profit(Request $r){$v=$r->validate(['entry'=>'required|numeric','exit'=>'required|numeric','lot'=>'required|numeric|gt:0','direction'=>'required|in:BUY,SELL','contract_size'=>'required|numeric|gt:0']);return $this->c->profit($v['entry'],$v['exit'],$v['lot'],$v['direction'],$v['contract_size']);}public function risk(Request $r){$v=$r->validate(['balance'=>'required|numeric|gt:0','risk_percent'=>'required|numeric|gt:0|max:100','entry'=>'required|numeric','stop_loss'=>'required|numeric','contract_size'=>'required|numeric|gt:0']);return $this->c->risk($v['balance'],$v['risk_percent'],$v['entry'],$v['stop_loss'],$v['contract_size']);}public function breakeven(Request $r){$v=$r->validate(['positions'=>'required|array|min:1|max:20','positions.*.entry'=>'required|numeric','positions.*.lot'=>'required|numeric|gt:0']);return $this->c->breakeven($v['positions']);}public function points(Request $r){$v=$r->validate(['price_1'=>'required|numeric','price_2'=>'required|numeric','tick_size'=>'required|numeric|gt:0']);$d=abs($v['price_2']-$v['price_1']);return ['price_difference'=>$d,'ticks'=>round($d/$v['tick_size'],2)];}}
